toolScript:
// --- UPGRADED PARALLAX SIMULATOR LOGIC ---
        let currentCrop = 1.0;
        let currentSensorName = "Full Frame";
        function setSensor(multiplier, name, btn) {
            currentCrop = multiplier;
            currentSensorName = name;
            // Remove active class from all buttons
            document.querySelectorAll('.sensor-btn').forEach(b => {
                b.classList.remove('active', 'ring-2', 'ring-orange-500');
            });
            // Add active class to clicked
            btn.classList.add('active', 'ring-2', 'ring-orange-500');
            updateSim();
        }
        function updateSim() {
            // Get User Inputs
            const focalInput = document.getElementById('focal-slider');
            const apertureInput = document.getElementById('aperture-slider');
            const isParallaxLocked = document.getElementById('dolly-toggle').checked;
            const focal = parseInt(focalInput.value);
            const aperture = parseFloat(apertureInput.value);
            const equiv = focal * currentCrop;
            // 1. Update UI Text
            document.getElementById('slider-val-display').innerText = focal + 'mm';
            document.getElementById('hud-focal').innerHTML = focal + '<span class="text-sm text-slate-500">mm</span>';
            document.getElementById('aperture-val-display').innerText = 'f/' + aperture.toFixed(1);
            document.getElementById('hud-aperture').innerText = 'f/' + aperture.toFixed(1);
            document.getElementById('stat-equiv').innerText = Math.round(equiv) + 'mm';
            // 2. Math: Horizontal Angle of View
            const angle = 2 * Math.atan(36 / (2 * equiv)) * (180 / Math.PI);
            const angleText = angle.toFixed(1) + '°';
            document.getElementById('hud-fov') ? document.getElementById('hud-fov').innerText = angleText : null;
            document.getElementById('stat-angle').innerText = angleText;
            // 3. Math: Bokeh (Depth of Field Blur)
            // Blur increases with longer focal lengths and wider apertures (lower f-stop numbers)
            let blurPx = (equiv / 12) / aperture;
            blurPx = Math.min(blurPx, 20); // Cap the maximum blur to keep the background somewhat visible
            // 4. Parallax Compression & Scale Logic
            const bgLayer = document.getElementById('bg-layer');
            const fgLayer = document.getElementById('fg-layer');
            const baseFocal = 14;
            const zoomScale = equiv / baseFocal;
            const visualScale = Math.min(zoomScale, 15); // Cap to prevent infinite zoom breaking viewport
            // Compression Stat
            document.getElementById('stat-comp').innerText = zoomScale.toFixed(1) + 'x';
            if (isParallaxLocked) {
                // DOLLY ZOOM MODE: Subject size stays locked, background compresses and blurs drastically.
                fgLayer.style.transform = `scale(1)`;
                bgLayer.style.transform = `scale(${visualScale})`;
                bgLayer.style.filter = `blur(${blurPx}px)`;
            } else {
                // STANDARD ZOOM: You stand still, everything just gets bigger.
                fgLayer.style.transform = `scale(${visualScale})`;
                bgLayer.style.transform = `scale(${visualScale})`;
                bgLayer.style.filter = `blur(${blurPx}px)`;
            }
        }
        function resetSim() {
            document.getElementById('focal-slider').value = 50;
            document.getElementById('aperture-slider').value = 2.8;
            document.getElementById('dolly-toggle').checked = false;
            // Find Full Frame button and click it programmatically
            const ffBtn = document.querySelector('.sensor-btn');
            if (ffBtn) setSensor(1.0, 'Full Frame', ffBtn);
        }
        // Initialize
        window.onload = function () {
            updateSim();
        };
